          {
            "topic": "vehicle",
            "question": "How long do I have to register my car and get a license?",
            "answer": "New residents have 60 days after establishing residency to register vehicles and get a New Hampshire driver's license. Registration runs through your town clerk plus the DMV.",
            "sourceUrl": "https://www.dmv.nh.gov/vehicles-boats-or-titles/vehicle-registrations/new-resident-new-hampshire",
            "sourceOrg": "New Hampshire Division of Motor Vehicles",
            "verification": "NH state hosts 403 non-browser clients; page title verified in a real browser 2026-08-14"
